<?php $items=all('produtos');$edit=isset($_GET['edit'])?one('produtos',(int)$_GET['edit']):null; ?>
<div class="two-col"><section class="panel"><div class="panel-header"><div><h2><?=$edit?'Editar produto':'Cadastrar produto'?></h2><p>Identifique a mercadoria e seu peso</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="save_product"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>">
<label>Nome do produto<input class="form-control" name="nome" required maxlength="150" placeholder="Ex.: Calça jeans" value="<?=h($edit['nome']??'')?>"></label>
<label>Código do produto<input class="form-control" name="codigo" required maxlength="50" placeholder="Ex.: CJ001" value="<?=h($edit['codigo']??'')?>"></label>
<label>Peso unitário (kg)<input class="form-control" name="peso_unitario" required type="number" min="0.001" step="0.001" placeholder="0.600" value="<?=h($edit['peso_unitario']??'')?>"></label>
<label>Quantidade em estoque<input class="form-control" name="quantidade" required type="number" min="0" max="100000000" step="1" placeholder="150" value="<?=h($edit['quantidade']??'')?>"></label>
<div class="form-actions"><button class="btn btn-purple" type="submit">✓ &nbsp;Salvar produto</button><?php if($edit):?><a class="btn btn-outline-secondary" href="index.php?page=produtos">Cancelar</a><?php endif;?></div></form></section>
<section class="panel"><div class="panel-header"><div><h2>Produtos cadastrados</h2><p><?=count($items)?> itens registrados</p></div></div><div class="table-responsive"><table class="table app-table"><thead><tr><th>Código</th><th>Produto</th><th>Peso</th><th>Estoque</th><th></th></tr></thead><tbody>
<?php foreach($items as $x):?><tr><td><span class="code-tag"><?=h($x['codigo'])?></span></td><td><?=h($x['nome'])?></td><td><?=number_format($x['peso_unitario'],3,',','.')?> kg</td><td><?=h($x['quantidade'])?></td><td class="action-cell"><a href="index.php?page=produtos&amp;edit=<?=$x['id']?>" class="text-link">Editar</a><form method="post" onsubmit="return confirm('Excluir este produto?');"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="produtos"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="link-danger" type="submit">Excluir</button></form></td></tr><?php endforeach;?>
<?php if(!$items):?><tr><td colspan="5" class="empty-state">Nenhum produto cadastrado.</td></tr><?php endif;?></tbody></table></div></section></div>
